contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // single test function: deposit an amount and assert contract balance increased by >= that amount
    function runTest(uint256 priorFund, uint256 depositAmount) public {
        // ensure this test contract holds enough ether to send depositAmount
        require(address(this).balance >= depositAmount);
        // bring the contract c to a known prior balance by optionally funding it via migrateTo from creator is not possible here,
        // so we instead record the prior balance as observed
        uint256 before = address(c).balance;

        // perform the deposit on c
        c.deposit{value: depositAmount}();

        uint256 after = address(c).balance;

        // The original had an assert preventing overflow of balances[msg.sender] so depositing a positive amount
        // must increase the contract's Ether balance by at least depositAmount. The mutant removing that assert
        // can enable scenarios (through overflow) that would not reflect the full increase at the balance mapping level,
        // but the observable contract ETH balance must still increase by the sent value. We assert this observable rule.
        assert(after - before >= depositAmount);
    }

    // Allow this contract to receive ETH so it can forward deposits in tests
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.deposit{value: amount}() { reverted = false; } catch { reverted = true; }
        // In the original contract deposit never reverts for any amount >= 0; the mutant can revert when overflow occurs.
        assert(reverted == false);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address sender, uint256 amount) public payable {
        require(address(this).balance >= amount, "need funds");
        // Attempt to deposit 'amount' from this test contract to c
        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // The original contract prevents an overflow by asserting balances[msg.sender] + amount > balances[msg.sender].
        // Thus, if amount > 0 the original will revert when adding amount would wrap; the mutant removed that guard and may accept such a deposit.
        // We express the general rule: if amount is nonzero, then deposit must either succeed only when it cannot wrap; equivalently, if it would wrap then it must revert.
        // Since we cannot read balances, we enforce that deposits of amount == 0 may succeed or revert, but deposits with amount > 0 must not succeed if they'd cause wrap.
        // We can detect wrapping by checking that after a successful deposit the contract's balance increased by exactly amount (no wrap at contract-level implies no wrap at mapping entry for same sender),
        // but address(c).balance is global and won't wrap in this context. Instead we rely on the fact that the original reverts whenever an overflow at the mapping entry would occur, so for amount > 0 such overflow-causing calls must revert.
        // Express rule: if amount > 0 then the call must not both succeed and cause a wrapping behavior is what we want to forbid; since we cannot observe mapping, we require that deposit with amount > 0 cannot succeed when amount is so large that amount + 1 == 0 (i.e., amount == type(uint256).max). This captures a general overflow-triggering value.
        // So we assert: if amount == type(uint256).max then deposit must revert.
        assert(!(amount == type(uint256).max && reverted == false));
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // amount is the Ether sent to deposit; caller is msg.sender of this tx
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount);
        bool reverted;
        try c.deposit{value: amount}() { reverted = false; } catch { reverted = true; }
        // If deposit succeeded (not reverted) then it must not be the case that
        // the caller had a nonzero balance and amount>0 such that addition would wrap.
        // We cannot read balances directly, so express wrap condition via modular arithmetic:
        // Let before = some value B in uint256; wrap occurs iff B != 0 && (B + amount) < B.
        // Since we cannot observe B, the original contract enforces that any successful deposit
        // cannot be one that would make (old + amount) < old. So we assert: if deposit succeeded
        // then it's not possible that amount>0 and that there exists some old>0 with (old+amount)<old.
        // That reduces to forbidding amount>0 with amount > 0 and amount > 0 (tautology) — to make
        // this check meaningful and only use parameters and reverted, we assert that if deposit
        // succeeded then amount == 0 OR deposit reverted. Rewriting into allowed form:
        assert(reverted || amount == 0);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, uint256 prior, uint256 v) public payable {
        // we cannot read c.balances directly (it's private), so simulate by using caller and value
        // Preconditions: value > 0 and prior + v would overflow uint256.
        require(v > 0, "need positive deposit");
        require(prior + v < prior, "must be overflow condition");
        // To cause deposit to operate on the provided caller, we must call from that address.
        // However tests run from this contract; we instead detect behavior difference via revert flag when calling deposit with value v.
        require(address(this).balance >= v, "insufficient funds to forward");
        bool reverted;
        try c.deposit{value: v}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // Rule: when v>0 and prior+v would overflow, the original contract (with assert) always reverts, so reverted must be true.
        // This captures that deposits that would wrap are rejected.
        assert(reverted == true);
    }
    receive() external payable {}
}

