pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor as a non-zero address to be meaningful
        vm.assume(depositor != address(0));

        // bound amount to full uint256 range (no narrowing) but ensure it's a payable scenario
        // vm.deal requires an address; give depositor sufficient ETH to send `amount`
        vm.deal(depositor, amount);

        // read prior balance via the public mapping getter
        uint256 before = getBalanceOf(depositor);

        // perform deposit as the depositor with the fuzzed amount
        vm.prank(depositor);
        // if amount is 0 this is still admissible; reference still satisfies rule (increase by 0)
        c.deposit{value: amount}();

        uint256 after = getBalanceOf(depositor);

        // General property: after == before + amount (uint256 addition without wrap)
        // This holds for the reference which asserted no overflow; the mutant that removed the assert
        // may wrap on overflow and make after != before + amount. We express the check using unchecked
        // uint256 sum to mirror Solidity wrapping behavior for detection: but here we assert the true
        // mathematical addition (which in Solidity is modular). To ensure the reference's protection is
        // being checked, we only accept cases where the normal addition does not wrap: i.e., before + amount >= before.
        // That condition is guaranteed for non-overflowing additions; the reference enforces it.

        // The single required assertion: the stored balance equals the non-wrapping sum (before + amount)
        // For inputs where before + amount would overflow, the reference contract's assert prevents the deposit
        // from completing; such inputs are excluded by the property by virtue of the reference guaranteeing no wrap.
        assertTrue(after == before + amount);
    }

    // helper to read the public mapping balances (auto-generated getter)
    function getBalanceOf(address who) internal returns (uint256) {
        // call the auto getter: C has mapping(address => uint256) balances; the getter is balances(address)
        return c.balances(who);
    }
}

