import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed depositor address and amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero to be a valid EOA in tests
        vm.assume(depositor != address(0));
        // bound amount to be any uint256 (no additional restriction) but ensure the depositor has funds to send
        // give depositor some ETH to send
        vm.deal(depositor, amount);

        // read balance before
        // There is no public getter 'balances' in C as given, so we cannot call c.balances(depositor).
        // But the test requirement allows reading address(c).balance to observe contract balance only.
        // To observe per-depositor stored balance we must rely on behavior through withdraw/refund.
        // Approach: call deposit from depositor then immediately attempt a withdraw of the same amount;
        // in the correct contract, after deposit the depositor's stored balance is >= previous, so withdrawing up to amount should succeed when amount <= stored balance.
        // However, to produce a universal property directly reading contract state we instead use the following technique:
        // - Make depositor deposit amount
        // - Then call deposit again with zero value (a no-op) to check that stored balance did not decrease as a result of the previous deposit
        // But since C does not expose balances publicly, we assert a general invariant via try/catch on withdraw:

        // First, perform initial deposit from depositor of amount
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Now try to withdraw amount. In the reference, if the stored balance increased correctly, withdraw(amount) should succeed.
        // In the mutant with overflow wrap, the stored balance could be less than amount and withdraw would revert.
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Assert: after depositing `amount`, it must be possible to withdraw `amount` (i.e., stored balance did not wrap below amount).
        // This is a general rule the reference satisfies for all inputs, and the overflow-removing mutant fails for some inputs
        // (when balances[msg.sender] + amount overflows and wraps below amount).
        assertTrue(ok);
    }
}

