pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor as a non-zero address (EOA is fine)
        vm.assume(depositor != address(0));
        // bound amount to [1, 2**256-1]
        amount = bound(amount, 1, type(uint256).max);

        // Arrange: ensure the depositor has enough ETH to send
        vm.deal(depositor, amount);

        // Record prior contract-observed balance for depositor via trying a deposit of 0 to read mapping indirectly is impossible;
        // instead perform a first deposit to set an initial prior balance we control.
        // We will create an initial balance 'prior' by making depositor send an initial_value.
        // Choose an initial_value such that prior + amount may overflow in mutant but is valid in reference.

        // We fuzz also by allowing depositor to perform an initial deposit value derived from amount to create potential overflow.
        uint256 initial = amount == 0 ? 1 : (type(uint256).max - amount + 1); // this causes prior + amount to wrap when added
        // Ensure initial is within payable funds: if initial > funds, cap it to depositor funds (but keep wide)
        if (initial > address(this).balance + amount) {
            // fund the depositor sufficiently
            vm.deal(depositor, initial);
        }

        // Make initial deposit as depositor to set balances[depositor] = initial in reference
        vm.prank(depositor);
        c.deposit{value: initial}();

        // Now record contract's observed balance for depositor by reading address(c).balance cannot distinguish per-depositor mapping.
        // However, we can reason about the mapping value via calling refund pattern: but refund pays out full balance and zeroes it,
        // which we can use to observe the stored balance for depositor.

        // Use a try/catch around refund invoked by depositor to capture returned balance via the amount of funds received.
        // To observe the mapping value without destroying state, we will perform the test on a freshly deployed contract copy.

        // For clarity and to adhere to the single-assert rule, recreate scenario on a fresh contract and perform two-step deposits then check via refund amount.
        C c2 = new C();

        // fund depositor for initial + amount
        vm.deal(depositor, initial + amount);

        // depositor makes initial deposit on c2
        vm.prank(depositor);
        c2.deposit{value: initial}();

        // depositor makes the fuzz deposit amount on c2
        vm.prank(depositor);
        c2.deposit{value: amount}();

        // Now call refund() as depositor and capture the refunded value to observe balances[depositor]
        // We'll use a helper contract to receive the refund and record the amount; but since depositor is an EOA in fuzz,
        // we instead employ a small Receiver helper that we deploy and then act as the depositor via its address.
    }
}

// Minimal helper receiver to act as depositor and capture refund amounts
contract Receiver {
    uint256 public received;
    C public target;
    constructor(C _target) {
        target = _target;
    }
    // allow funding
    receive() external payable {
        received += msg.value;
    }
    function doDeposit(uint256 v) external payable {
        target.deposit{value: msg.value}();
    }
    function doRefund() external {
        target.refund();
    }
}

