pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero to be a valid actor
        vm.assume(depositor != address(0));
        // bound amount to wide range but allow large values to trigger overflow
        amount = bound(amount, 0, type(uint256).max);

        // fund the depositor so they can send 'amount' wei
        vm.deal(depositor, amount);

        // record balance before
        uint256 before = address(c).balance;
        // Try to read depositor's stored balance via low-level call to public mapping getter is not available
        // but we can observe change via contract's behaviour: perform deposit and then check that the depositor's recorded
        // balance did not decrease by querying by making deposit and then attempting a refund to the depositor
        // However refund() sends the entire stored balance to msg.sender and then zeroes it. We can use that to observe stored balance.

        // First, ensure any prior stored balance for depositor is some value by making at least one deposit from that depositor.
        // Do an initial small deposit of 1 wei to set a prior balance that the fuzzer can then combine with 'amount' to cause overflow.
        uint256 initial = 1;
        vm.deal(depositor, initial + amount); // ensure enough funds for both deposits

        vm.prank(depositor);
        c.deposit{value: initial}();

        // record stored balance after initial deposit via performing a refund (which returns the stored balance)
        vm.prank(depositor);
        // call refund to retrieve stored balance; use try/catch to detect success
        bool ok;
        try c.refund() {
            ok = true;
        } catch {
            ok = false;
        }
        // refund should succeed on reference and mutant; assume success to continue observation
        vm.assume(ok);

        // After refund, the stored balance is zero; now we need to set an arbitrary prior stored balance that can be large.
        // We simulate a prior large balance by performing a low-level sequence: directly call deposit multiple times from depositor.
        // Make a big prior balance by sending a controlled large_old value using vm.prank depositor.
        uint256 large_old = (type(uint256).max / 2) + 2; // large value to enable overflow with another large amount
        vm.deal(depositor, large_old + amount);
        vm.prank(depositor);
        c.deposit{value: large_old}();

        // Now record the contract-observable total balance before the targeted deposit
        uint256 contractBalanceBefore = address(c).balance;

        // perform the fuzzed deposit of 'amount' from depositor
        vm.prank(depositor);
        c.deposit{value: amount}();

        // After deposit, the contract's balance must have increased by exactly 'amount' (this is independent of the internal mapping overflow)
        // But the required observable for this test is that the depositor's recorded mapping balance did not decrease. We can detect a decrease by
        // calling refund(): refund sends the stored mapping balance to msg.sender and zeroes it; comparing the refunded amount to the expected
        // prior stored balance plus amount lets us detect wraparound (a decrease).

        // Call refund and capture whether it sends at least as much as the prior stored balance (large_old + amount)
        vm.prank(depositor);
        // To capture the refunded amount we compare contract's balance drop across refund call
        uint256 beforeRefund = address(depositor).balance;
        uint256 beforeContract = address(c).balance;
        vm.prank(depositor);
        try c.refund() {
            // success
        } catch {
            // if refund reverts something is wrong; treat as failure of invariant
        }
        uint256 afterRefund = address(depositor).balance;
        uint256 afterContract = address(c).balance;

        uint256 refunded = afterRefund - beforeRefund;

        // The general rule: depositor's recorded balance after deposit >= recorded balance before deposit.
        // We observed 'large_old' as prior stored balance and then deposited 'amount', so refunded should be >= large_old.
        assertTrue(refunded >= large_old);
    }
}

