pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // We need depositor to be a non-zero address (EOA); the fuzzer can give zero address which is admissible
        // but using vm.assume to avoid the zero-address which can't be pranked/useful
        vm.assume(depositor != address(0));

        // Make depositor have some existing on-chain balance for sending Ether
        // Ensure amount is at least 1 to exercise non-zero deposits (keeps domain wide)
        amount = bound(amount, 1, type(uint256).max);

        // We'll arrange the prior recorded balance in c for this depositor by performing one or more deposits
        // The general rule we assert: if prior + amount does not overflow, then after deposit recorded balance == prior + amount
        // To keep the domain wide we allow any prior produced by a first deposit of some priorAmount (also fuzzed via deposition)

        // Choose a priorAmount such that priorAmount can be anything (we set it from block.timestamp to introduce variability)
        uint256 priorAmount = uint256(uint160(depositor)) % (2**200) + 1; // wide variety, non-zero

        // Fund depositor externally so they can call deposit
        vm.deal(depositor, priorAmount + amount + 1 ether);

        // First, have depositor deposit priorAmount to set c.balances[depositor] = priorAmount (assuming correct contract)
        vm.prank(depositor);
        c.deposit{value: priorAmount}();

        // read the recorded prior balance from c by calling refund()-free read: there is no getter for balances (private), so we can't read it directly
        // However, we can observe address(c).balance which increases by deposits; but we need to assert about stored balances for the depositor.
        // The contract's balances mapping is not public, so we cannot directly read it. Instead, we reason via behavior: perform a second deposit and then immediately attempt to withdraw the expected total
        // We'll perform the second deposit of `amount` and then attempt to withdraw (priorAmount + amount). The reference contract will allow withdraw of that total if and only if recorded balance equals prior+amount (and no overflow occurred).

        // If priorAmount + amount does not overflow, reference will allow successful withdraw of total; mutant may wrap and make withdraw fail.

        // Ensure the combined withdraw target is not exceeding uint256 (it will wrap in mutant case)
        // We must restrict to admissible domain where priorAmount + amount does NOT overflow, because the asserted property is about that case
        vm.assume(priorAmount + amount > priorAmount); // no overflow

        // Now perform the second deposit of `amount`
        vm.prank(depositor);
        c.deposit{value: amount}();

        // Try to withdraw the combined total from the contract as the depositor. If the stored balance equals prior+amount, withdraw should succeed.
        bool ok;
        try c.withdraw(priorAmount + amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees ok == true for all admissible inputs (where prior+amount does not overflow).
        // The mutant that removed the assert can allow overflow in earlier deposit, but we've constrained to no-overflow in prior+amount, so reference must always succeed.
        assertTrue(ok);
    }
}

