contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: parameters control deposit value and withdraw amount
    function run(uint256 initialFund, uint256 zeroDeposit) public {
        // make sure this contract can send initialFund as ether
        require(address(this).balance >= initialFund + zeroDeposit);

        // fund the target contract by sending a positive deposit from this contract
        c.deposit{value: initialFund}();

        // record contract balances observable externally
        uint256 before = address(c).balance;

        // perform a zero-value deposit call (this is the differing action)
        c.deposit{value: zeroDeposit}();

        uint256 after = address(c).balance;

        // The distinguishing property: if zeroDeposit == 0 then after == before (no change in contract balance)
        // This holds on the original (which accepts zero-value calls and performs assert that allows zero),
        // but is violated by the mutant which requires msg.value > 0 and would revert the zero-value call.
        assert(!(zeroDeposit == 0) || after == before);
    }

    // allow this test contract to receive ether for funding
    receive() external payable {}
}

