pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz params: actor address and an amount (uint256) that will be used as msg.value
    function testFuzz_property(address actor, uint256 amount) public {
        // keep domain wide but ensure actor is non-zero (EOA or any address) and amount is not absurdly large
        vm.assume(actor != address(0));
        // bound amount to a reasonable range so vm.deal can fund the actor
        amount = bound(amount, 0, 1 ether);

        // fund the actor so they can send 'amount'
        vm.deal(actor, amount);

        // call deposit from actor with `amount` value; capture whether call succeeded
        bool ok;
        vm.prank(actor);
        try c.deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

